<script setup lang="ts">
definePageMeta({ middleware: ['auth', 'barber'], layout: 'dashboard' })
interface Appointment { id: string, code: string, hora_inicio: string, hora_fin: string, estado: string, client: { user: { name: string | null } }, service: { nombre: string | null } }
interface AgendaResponse { data: Appointment[], range: { label: string }, stats: Record<string, number> }
const { apiFetch } = useApi()
const period = ref<'day' | 'week'>('day'); const estado = ref(''); const offset = ref(0); const busyCode = ref(''); const message = ref('')
const { data: response, pending, error, refresh } = await useAsyncData<AgendaResponse>('barber-agenda', () => apiFetch('/barber/agenda', { query: { period: period.value, estado: estado.value || undefined, offset: offset.value } }), { watch: [period, estado, offset], lazy: true })
const appointments = computed(() => response.value?.data ?? []); const stats = computed(() => response.value?.stats ?? {})
const labels: Record<string, string> = { pendiente: 'Pendiente', confirmada: 'Confirmada', en_proceso: 'En proceso', completada: 'Completada', cancelada: 'Cancelada', no_asistio: 'No asistio' }
const classes: Record<string, string> = { pendiente: 'text-amber-300 bg-amber-500/10', confirmada: 'text-blue-300 bg-blue-500/10', en_proceso: 'text-sky-300 bg-sky-500/10', completada: 'text-emerald-300 bg-emerald-500/10', cancelada: 'text-red-400 bg-red-500/10', no_asistio: 'text-orange-300 bg-orange-500/10' }
const nextState: Record<string, string> = { pendiente: 'confirmada', confirmada: 'en_proceso', en_proceso: 'completada' }
async function changeStatus(appt: Appointment, status: string) { busyCode.value = appt.code; message.value = ''; try { await apiFetch(`/appointments/${appt.code}/status`, { method: 'PATCH', body: { estado: status } }); message.value = 'Estado actualizado.'; await refresh() } catch (err: unknown) { message.value = (err as { data?: { message?: string } })?.data?.message ?? 'No se pudo actualizar la cita.' } finally { busyCode.value = '' } }
</script>
<template><div class="p-4 sm:p-6 lg:p-8"><header class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-xs uppercase tracking-widest text-muted">Mi espacio</p><h1 class="mt-1 text-2xl font-semibold text-ink">Mi <span class="text-gold">Agenda</span></h1><p class="mt-1 text-sm text-muted">{{ response?.range.label ?? 'Tus citas programadas' }}</p></div><div class="flex gap-2"><button class="rounded-lg border border-line px-3 py-2 text-sm text-muted" @click="offset -= period === 'week' ? 7 : 1">Anterior</button><button class="rounded-lg border border-line px-3 py-2 text-sm text-ink" @click="offset = 0">Hoy</button><button class="rounded-lg border border-line px-3 py-2 text-sm text-muted" @click="offset += period === 'week' ? 7 : 1">Siguiente</button></div></header><section class="mb-5 grid grid-cols-2 gap-3 lg:grid-cols-4"><div v-for="card in [{k:'total_period',l:'En periodo'},{k:'completed_period',l:'Completadas'},{k:'productivity',l:'Productividad',s:'%'},{k:'income_total',l:'Ingreso historico',s:'$'}]" :key="card.k" class="ui-card p-4"><p class="text-xs uppercase text-muted">{{ card.l }}</p><p class="mt-2 text-2xl font-black text-ink">{{ card.s === '$' ? '$' : '' }}{{ stats[card.k] ?? 0 }}{{ card.s === '%' ? '%' : '' }}</p></div></section><div class="mb-5 flex gap-3"><select v-model="period" class="rounded-lg border border-line bg-main px-3 py-2 text-sm text-ink"><option value="day">Dia</option><option value="week">Semana</option></select><select v-model="estado" class="rounded-lg border border-line bg-main px-3 py-2 text-sm text-ink"><option value="">Todos los estados</option><option v-for="(label, key) in labels" :key="key" :value="key">{{ label }}</option></select></div><p v-if="message" class="mb-4 text-sm text-gold">{{ message }}</p><p v-if="pending" class="text-sm text-muted">Cargando agenda...</p><p v-else-if="error" class="text-sm text-red-400">No se pudo cargar la agenda.</p><section v-else class="space-y-3"><article v-for="appt in appointments" :key="appt.id" class="ui-card flex flex-col gap-4 p-5 sm:flex-row sm:items-center"><div class="w-24 shrink-0"><p class="font-black text-gold">{{ appt.hora_inicio.slice(0,5) }}</p><p class="text-xs text-muted">{{ appt.hora_fin.slice(0,5) }}</p></div><div class="min-w-0 flex-1"><p class="font-bold text-ink">{{ appt.client.user.name ?? 'Cliente' }}</p><p class="text-sm text-muted">{{ appt.service.nombre ?? 'Servicio' }}</p></div><span class="rounded-full px-3 py-1 text-xs font-bold" :class="classes[appt.estado]">{{ labels[appt.estado] ?? appt.estado }}</span><div class="flex gap-2"><button v-if="nextState[appt.estado]" :disabled="busyCode === appt.code" class="rounded-lg bg-gold px-3 py-2 text-xs font-bold text-black disabled:opacity-50" @click="changeStatus(appt, nextState[appt.estado])">{{ labels[nextState[appt.estado]] }}</button><button v-if="!['completada','cancelada','no_asistio'].includes(appt.estado)" class="rounded-lg border border-red-500/20 px-3 py-2 text-xs text-red-400" @click="changeStatus(appt, 'cancelada')">Cancelar</button></div></article><div v-if="!appointments.length" class="ui-card py-16 text-center text-sm text-muted">No hay citas en este periodo.</div></section></div></template>
